@js:
sort=[];
burl=source.getKey().match(/([^\#]+)\#/)[1];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
function fl(a){
		url=burl+`/api/newBookRoom/list?clsID=${a}&pageNum=1&pageSize=100`;
		return  JSON.parse(java.ajax(url)).data;
}
function ul(b){
	url = `/api/newClassify/list?classfyIDs=${b}&pageNum={{page}}&pageSize=10`;
	return url;
}		
//全部：1
		[["男生",fl(98).contentList],
		["女频",fl(122).contentList],
		["出版",fl(79).contentList]].map([tit1,list]=>{				
    	[["连载","2"],["完本","3"]].map([tit2,status]=>{	   			
				push(tit1+'-'+tit2, null, 1, 1);
				list.map(($,index)=>{
					title = $.title;
					id = $.scheme.match(/classfyIDs=(\d+,\d+),/)[1]
					label_id=id+','+status;
					url=ul(label_id);
					if(index+1 <= list.length - list.length%3){
						push(title, url, 1, 0.25);}
						else{ push(title, url, 0, 0.29);}
        });   
       });
  });

JSON.stringify(sort);

