function decodeStr(src){
  var {java}=this
  c =((src.match(/var c+( = |=)+("(.+)"|'(.+)')/)||[])[2]||'').replace(/"|'/g,'')
dataStr = c.slice(Number(c.slice(4,6))+6,Number(c.length-Number(-c.slice(4,6)))).replace(/_/g,'8L3A+').replace(/-/g,'PHA+')
return java.base64Decode(dataStr)
}

